section.codeblock:
SELECT id, variant_get(v, '$.name', 'string') AS name
FROM events
WHERE variant_get(v, '$.age', 'int') > 18;

SELECT variant_get(variant_get(v, '$.context'), '$.page') FROM events;

SELECT try_variant_get(v, '$.items[0].quantity', 'int') FROM events;

SELECT variant_to_json(variant_get(v, '$.items')) FROM events;
